let data = msg.payload;
if (typeof data === 'string') {
    try { data = JSON.parse(data); } catch(e) { return [null, {payload: 'Invalid JSON: ' + e}]; }
}

// Validasi Skema Wajib (Bagian 4.3)
if (!data || data.schema !== 'kampus.telemetry.v1' || !data.device_id || !data.domain || !data.gedung || !data.ruang || !data.metrics) {
    return [null, {payload: 'Rejected schema: ' + JSON.stringify(data)}];
}

if (typeof data.ts !== 'number') {
    return [null, {payload: 'Rejected invalid ts: ' + data.ts}];
}

// Format InfluxDB Point
let fields = {};
for (let k in data.metrics) {
    let val = data.metrics[k];
    if (typeof val === 'number') {
        fields[k] = val;
    } else if (typeof val === 'boolean') {
        fields[k] = val ? 1 : 0;
    }
}

let tags = {
    domain: data.domain,
    gedung: data.gedung,
    ruang: data.ruang,
    device_id: data.device_id
};

let validMsg = {
    measurement: 'telemetry',
    payload: [fields, tags],
    timestamp: data.ts * 1000000, // nanoseconds
    original: data
};

// Output 1: ke InfluxDB
// Output 2: ke Audit Log (jika reject)
// Output 3: ke Tab Rules Air
return [validMsg, null, {payload: data}];

let data = msg.payload;
if (typeof data === 'string') {
    try { data = JSON.parse(data); } catch(e) { return [null, {payload: 'Invalid JSON'}]; }
}

if (!data || data.schema !== 'kampus.status.v1' || !data.device_id || !data.domain || !data.status) {
    return [null, {payload: 'Rejected status schema: ' + JSON.stringify(data)}];
}

let isOnline = (data.status.toLowerCase() === 'online') ? 1 : 0;
let fields = { online: isOnline };
let tags = {
    domain: data.domain,
    gedung: data.gedung || '',
    ruang: data.ruang || '',
    device_id: data.device_id
};

let validMsg = {
    measurement: 'status',
    payload: [fields, tags],
    timestamp: (data.ts || Date.now()) * 1000000
};

return [validMsg, null, {payload: data}];

let data = msg.payload;
if (!data || data.domain !== 'air') {
    return null;
}

let m = data.metrics || {};
let co2 = m.co2_ppm;
let pm25 = m.pm25_ugm3;
let noise = m.noise_db;

let alerts = [];

// 1. CO2 Threshold: >1000 warning, >1500 critical
if (co2 > 1500) {
    alerts.push({
        device_id: data.device_id,
        domain: 'air',
        code: 'CO2_HIGH',
        severity: 'critical',
        message: 'Kadar CO2 sangat tinggi mencapai ' + co2 + ' ppm di ' + data.ruang,
        value: co2,
        context: { ruang: data.ruang, gedung: data.gedung }
    });
} else if (co2 > 1000) {
    alerts.push({
        device_id: data.device_id,
        domain: 'air',
        code: 'CO2_HIGH',
        severity: 'warning',
        message: 'Kadar CO2 melebihi batas 1000 ppm (' + co2 + ' ppm) di ' + data.ruang,
        value: co2,
        context: { ruang: data.ruang, gedung: data.gedung }
    });
}

// 2. PM2.5 Threshold: >35 warning, >75 critical
if (pm25 > 75) {
    alerts.push({
        device_id: data.device_id,
        domain: 'air',
        code: 'PM25_HIGH',
        severity: 'critical',
        message: 'Partikulat PM2.5 sangat berbahaya (' + pm25 + ' ug/m3) di ' + data.ruang,
        value: pm25,
        context: { ruang: data.ruang, gedung: data.gedung }
    });
} else if (pm25 > 35) {
    alerts.push({
        device_id: data.device_id,
        domain: 'air',
        code: 'PM25_HIGH',
        severity: 'warning',
        message: 'Partikulat PM2.5 di atas ambang batas (' + pm25 + ' ug/m3) di ' + data.ruang,
        value: pm25,
        context: { ruang: data.ruang, gedung: data.gedung }
    });
}

// 3. Noise Threshold: >70 warning
if (noise > 70) {
    alerts.push({
        device_id: data.device_id,
        domain: 'air',
        code: 'NOISE_HIGH',
        severity: 'warning',
        message: 'Tingkat kebisingan bising mencapai ' + noise + ' dB di ' + data.ruang,
        value: noise,
        context: { ruang: data.ruang, gedung: data.gedung }
    });
}

if (alerts.length === 0) {
    return null;
}

// Kembalikan setiap alert sebagai pesan tersendiri
return [alerts.map(a => ({
    payload: a,
    headers: {
        'Content-Type': 'application/json',
        'X-API-Key': env.get('API_KEY')
    }
}))];

let data = msg.payload;
if (!data || data.domain !== 'energy') {
    return null;
}

const tsMs = (typeof data.ts === 'number') ? data.ts : Date.now();
const deviceId = data.device_id;
const gedung = data.gedung || 'bsd-a';
const ruang = data.ruang || '';
const m = data.metrics || {};
const powerW = Number(m.power_w);
const energyKwh = Number(m.energy_kwh || 0);

const wasteThresholdW = Number(env.get('ENERGY_WASTE_THRESHOLD_W')) || 200;
const wasteDurationMs = (Number(env.get('ENERGY_WASTE_DURATION_SEC')) || 120) * 1000;
const highLoadThresholdW = Number(env.get('ENERGY_HIGH_LOAD_THRESHOLD_W')) || 3000;
const highLoadDurationMs = (Number(env.get('ENERGY_HIGH_LOAD_DURATION_SEC')) || 60) * 1000;
const workStart = Number(env.get('ENERGY_WORK_START_HOUR')) || 7;
const workEnd = Number(env.get('ENERGY_WORK_END_HOUR')) || 18;

let breachSince = flow.get('energyBreachSince') || {};
let activeAlerts = flow.get('energyActiveAlerts') || {};
let lastSeen = flow.get('energyLastSeen') || {};

// Catat telemetri masuk untuk watchdog OFFLINE
lastSeen[deviceId] = { ts: tsMs, gedung, ruang, online: true };

let alertsToPost = [];
let resolveLogs = [];

// Auto-resolve OFFLINE bila perangkat kembali mengirim telemetri
const offKey = deviceId + ':OFFLINE';
if (activeAlerts[offKey]) {
    resolveLogs.push({
        event: 'AUTO_RESOLVED',
        code: 'OFFLINE',
        device_id: deviceId,
        ruang,
        resolved_ts: tsMs,
        note: 'Telemetri kembali diterima dari ' + deviceId
    });
    delete activeAlerts[offKey];
}

// Cek jam kerja WIB (Senin-Jumat 07:00-18:00 UTC+7)
const wibDate = new Date(tsMs + 7 * 3600 * 1000);
const wibDay = wibDate.getUTCDay();
const wibHour = wibDate.getUTCHours();
const isWorkHour = (wibDay >= 1 && wibDay <= 5 && wibHour >= workStart && wibHour < workEnd);
const isAfterHours = (!isWorkHour) || Boolean(data.sim_after_hours);

function evalSustained(key, isBreaching, durationMs, buildAlert, resolveNote) {
    if (isBreaching) {
        if (breachSince[key] === undefined) {
            breachSince[key] = tsMs;
        }
        const elapsedMs = tsMs - breachSince[key];
        if (elapsedMs >= durationMs) {
            if (activeAlerts[key]) {
                // Deduplikasi: alert sudah aktif
                activeAlerts[key].occurrence_count = (activeAlerts[key].occurrence_count || 1) + 1;
                activeAlerts[key].last_seen_ts = tsMs;
            } else {
                const durSec = Math.round(elapsedMs / 1000);
                const alertObj = buildAlert(durSec);
                activeAlerts[key] = { ...alertObj, triggered_ts: tsMs, last_seen_ts: tsMs, occurrence_count: 1 };
                alertsToPost.push(alertObj);
            }
        }
    } else {
        delete breachSince[key];
        if (activeAlerts[key]) {
            resolveLogs.push({
                event: 'AUTO_RESOLVED',
                code: activeAlerts[key].code,
                device_id: deviceId,
                ruang,
                resolved_ts: tsMs,
                note: resolveNote
            });
            delete activeAlerts[key];
        }
    }
}

// 1. WASTE_AFTER_HOURS (warning): power_w > 200 W di luar jam kerja selama >= 2 menit
evalSustained(
    deviceId + ':WASTE_AFTER_HOURS',
    isAfterHours && powerW > wasteThresholdW,
    wasteDurationMs,
    (durSec) => ({
        device_id: deviceId,
        domain: 'energy',
        code: 'WASTE_AFTER_HOURS',
        severity: 'warning',
        message: 'Pemborosan daya di luar jam kerja pada ' + ruang + ' (' + powerW + ' W > ' + wasteThresholdW + ' W selama ' + durSec + ' dtk)',
        value: powerW,
        context: {
            gedung,
            ruang,
            duration_sec: durSec,
            threshold_w: wasteThresholdW,
            energy_kwh: energyKwh,
            simulated_after_hours: Boolean(data.sim_after_hours)
        }
    }),
    'Konsumsi daya di ' + ruang + ' kembali normal (' + powerW + ' W)'
);

// 2. HIGH_LOAD (critical): power_w > 3000 W selama >= 1 menit
evalSustained(
    deviceId + ':HIGH_LOAD',
    powerW > highLoadThresholdW,
    highLoadDurationMs,
    (durSec) => ({
        device_id: deviceId,
        domain: 'energy',
        code: 'HIGH_LOAD',
        severity: 'critical',
        message: 'Beban daya sangat tinggi di ' + ruang + ' mencapai ' + powerW + ' W (> ' + highLoadThresholdW + ' W selama ' + durSec + ' dtk)',
        value: powerW,
        context: {
            gedung,
            ruang,
            duration_sec: durSec,
            threshold_w: highLoadThresholdW,
            energy_kwh: energyKwh
        }
    }),
    'Beban daya di ' + ruang + ' kembali aman (' + powerW + ' W)'
);

flow.set('energyBreachSince', breachSince);
flow.set('energyActiveAlerts', activeAlerts);
flow.set('energyLastSeen', lastSeen);

const outAlerts = alertsToPost.length > 0
    ? alertsToPost.map(a => ({
        payload: a,
        headers: {
            'Content-Type': 'application/json',
            'X-API-Key': env.get('API_KEY')
        }
    }))
    : null;

const outResolves = resolveLogs.length > 0
    ? resolveLogs.map(r => ({ payload: r }))
    : null;

if (!outAlerts && !outResolves) {
    return null;
}
return [outAlerts, outResolves];

let data = msg.payload;
if (typeof data === 'string') {
    try { data = JSON.parse(data); } catch (e) { return null; }
}
if (!data || data.domain !== 'energy' || !data.device_id) {
    return null;
}

const tsMs = (typeof data.ts === 'number') ? data.ts : Date.now();
const deviceId = data.device_id;
const gedung = data.gedung || 'bsd-a';
const ruang = data.ruang || '';
const status = String(data.status || '').toLowerCase();

let activeAlerts = flow.get('energyActiveAlerts') || {};
let lastSeen = flow.get('energyLastSeen') || {};
const offKey = deviceId + ':OFFLINE';

if (status === 'offline') {
    const prev = lastSeen[deviceId] || {};
    lastSeen[deviceId] = { ts: tsMs, gedung: gedung || prev.gedung || 'bsd-a', ruang: ruang || prev.ruang || '', online: false };
    flow.set('energyLastSeen', lastSeen);

    if (activeAlerts[offKey]) {
        activeAlerts[offKey].occurrence_count = (activeAlerts[offKey].occurrence_count || 1) + 1;
        flow.set('energyActiveAlerts', activeAlerts);
        return null;
    }

    const alertObj = {
        device_id: deviceId,
        domain: 'energy',
        code: 'OFFLINE',
        severity: 'critical',
        message: 'KWh Meter ' + deviceId + ' (' + (ruang || prev.ruang || '') + ') terputus dari broker (LWT offline)',
        value: 0,
        context: { gedung: gedung || prev.gedung || 'bsd-a', ruang: ruang || prev.ruang || '', trigger: 'lwt_status' }
    };
    activeAlerts[offKey] = { ...alertObj, triggered_ts: tsMs, occurrence_count: 1 };
    flow.set('energyActiveAlerts', activeAlerts);

    return [{
        payload: alertObj,
        headers: {
            'Content-Type': 'application/json',
            'X-API-Key': env.get('API_KEY')
        }
    }, null];
}

if (status === 'online' || status === 'alive') {
    const prev = lastSeen[deviceId] || {};
    lastSeen[deviceId] = { ts: tsMs, gedung: gedung || prev.gedung || 'bsd-a', ruang: ruang || prev.ruang || '', online: true };
    flow.set('energyLastSeen', lastSeen);

    if (activeAlerts[offKey]) {
        delete activeAlerts[offKey];
        flow.set('energyActiveAlerts', activeAlerts);
        return [null, {
            payload: {
                event: 'AUTO_RESOLVED',
                code: 'OFFLINE',
                device_id: deviceId,
                ruang: ruang || prev.ruang || '',
                resolved_ts: tsMs,
                note: 'Perangkat kembali ' + status
            }
        }];
    }
}

return null;

const nowMs = Date.now();
const timeoutMs = (Number(env.get('ENERGY_OFFLINE_TIMEOUT_SEC')) || 60) * 1000;

let lastSeen = flow.get('energyLastSeen') || {};
let activeAlerts = flow.get('energyActiveAlerts') || {};
let alertsToPost = [];

for (const [deviceId, info] of Object.entries(lastSeen)) {
    const silentMs = nowMs - info.ts;
    const offKey = deviceId + ':OFFLINE';
    if (silentMs >= timeoutMs && !activeAlerts[offKey]) {
        const silentSec = Math.round(silentMs / 1000);
        const alertObj = {
            device_id: deviceId,
            domain: 'energy',
            code: 'OFFLINE',
            severity: 'critical',
            message: 'Tidak ada telemetri/heartbeat dari ' + deviceId + ' (' + info.ruang + ') selama ' + silentSec + ' detik',
            value: silentSec,
            context: {
                gedung: info.gedung || 'bsd-a',
                ruang: info.ruang || '',
                trigger: 'no_data_timeout',
                silent_sec: silentSec
            }
        };
        activeAlerts[offKey] = { ...alertObj, triggered_ts: nowMs, occurrence_count: 1 };
        alertsToPost.push(alertObj);
    }
}

flow.set('energyActiveAlerts', activeAlerts);

if (alertsToPost.length === 0) {
    return null;
}

return [alertsToPost.map(a => ({
    payload: a,
    headers: {
        'Content-Type': 'application/json',
        'X-API-Key': env.get('API_KEY')
    }
}))];
